import { test } from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { fillChangelogSection, newestRelease, parseCommitSubject, syncRoadmap, syncRoadmapPageDoc } from './sync-release.ts'

const CHANGELOG = `# Changelog

## [unreleased]

## [0.21.2] - 2026-10-23

### Bug Fixes

- Send max_completion_tokens instead of max_tokens ([#257](https://github.com/UmaiTech/aura-llm-gateway/pull/257))

<!-- generated by git-cliff -->

## [0.21.1] - 2026-10-23

### Bug Fixes

- Older fix ([#235](https://github.com/UmaiTech/aura-llm-gateway/pull/235))
`

const SUBJECTS = [
  'chore: sync SDK versions to 0.21.2',
  'chore: release v0.21.2',
  'fix(openai): send max_completion_tokens instead of max_tokens (#257)',
  'feat(landing): footer says "Made with love in Stockholm", links umai-tech.com (#255)',
  'fix(landing): reload once when a docs chunk is gone after a deploy (#256)',
  'docs(readme): designed header, product screenshots and a quick try-it (#254)',
  'chore(deps): bump something (#300)',
  'Merge branch main',
]

test('newestRelease reads the first release heading', () => {
  assert.deepEqual(newestRelease(CHANGELOG), { version: '0.21.2', date: '2026-10-23' })
})

test('parseCommitSubject groups like cliff.toml and skips release bookkeeping', () => {
  assert.deepEqual(parseCommitSubject('feat(admin,landing): link pages (#252)'), { group: 'Features', text: 'Link pages', pr: 252 })
  assert.deepEqual(parseCommitSubject('fix!: drop x'), { group: 'Bug Fixes', text: 'Drop x', pr: undefined })
  assert.equal(parseCommitSubject('chore: release v0.21.2'), undefined)
  assert.equal(parseCommitSubject('chore: sync SDK versions to 0.21.2'), undefined)
  assert.equal(parseCommitSubject('chore(deps): bump x'), undefined)
  assert.equal(parseCommitSubject('Update file.tsx'), undefined)
})

test('fillChangelogSection adds the commits release-plz dropped, grouped, once', () => {
  const filled = fillChangelogSection(CHANGELOG, '0.21.2', SUBJECTS)
  const section = filled.slice(filled.indexOf('## [0.21.2]'), filled.indexOf('## [0.21.1]'))
  assert.equal(
    section,
    `## [0.21.2] - 2026-10-23

### Bug Fixes

- Send max_completion_tokens instead of max_tokens ([#257](https://github.com/UmaiTech/aura-llm-gateway/pull/257))
- Reload once when a docs chunk is gone after a deploy ([#256](https://github.com/UmaiTech/aura-llm-gateway/pull/256))

### Documentation

- Designed header, product screenshots and a quick try-it ([#254](https://github.com/UmaiTech/aura-llm-gateway/pull/254))

### Features

- Footer says "Made with love in Stockholm", links umai-tech.com ([#255](https://github.com/UmaiTech/aura-llm-gateway/pull/255))

<!-- generated by git-cliff -->

`,
  )
  assert.ok(filled.endsWith('- Older fix ([#235](https://github.com/UmaiTech/aura-llm-gateway/pull/235))\n'))
  assert.equal(fillChangelogSection(filled, '0.21.2', SUBJECTS), filled)
})

const ROADMAP = `export const RECONCILED = {
  date: '2026-10-22',
  /** main commit the release history was reconciled against. */
  revision: '81334f2',
} as const

export const RELEASES: Release[] = [
  { version: '0.21.1', date: '2026-10-23', tagged: false },
  { version: '0.21.0', date: '2026-10-23', tagged: true },
]

export const ROADMAP: RoadmapItem[] = [
  // ── Merged to main, not in a release yet ──────────────────────────────
  {
    id: 'footer',
    title: 'Footer',
    status: 'merged-unreleased',
    area: 'site',
    description: 'Made with love.',
    evidenceLinks: [pr(255), UNRELEASED],
  },

  // ── Released ─────────────────────────────────────────────────────────
  released('0.21.1', {
    id: 'streaming-fixes',
    evidenceLinks: [pr(235)],
  }),

  // ── Planned ──────────────────────────────────────────────────────────
  {
    id: 'later',
    status: 'planned',
  },
]
`

const SYNC = { version: '0.21.2', date: '2026-10-24', tags: new Set(['v0.21.0', 'v0.21.1']), revision: 'a6472af' }

test('syncRoadmap lists the release, moves merged items into it and is idempotent', () => {
  const synced = syncRoadmap(ROADMAP, SYNC)
  assert.match(synced, /date: '2026-10-24',\n {2}\/\*\*/)
  assert.match(synced, /revision: 'a6472af',/)
  assert.match(
    synced,
    /RELEASES: Release\[\] = \[\n {2}\{ version: '0\.21\.2', date: '2026-10-24', tagged: false \},\n {2}\{ version: '0\.21\.1', date: '2026-10-23', tagged: true \},/,
  )
  assert.ok(
    synced.includes(`  // ── Merged to main, not in a release yet ──────────────────────────────
  // (none: everything merged so far shipped in v0.21.2)

  // ── Released ─────────────────────────────────────────────────────────
  released('0.21.2', {
    id: 'footer',
    title: 'Footer',
    area: 'site',
    description: 'Made with love.',
    evidenceLinks: [pr(255), changelogLink('0.21.2', '2026-10-24')],
  }),
  released('0.21.1', {`),
  )
  assert.ok(synced.includes("    id: 'later',\n    status: 'planned',"))
  assert.equal(syncRoadmap(synced, SYNC), synced)
})

test('syncRoadmap handles the real roadmap.ts', () => {
  const real = readFileSync(new URL('../../apps/landing/src/lib/roadmap.ts', import.meta.url), 'utf8')
  const synced = syncRoadmap(real, { ...SYNC, version: '99.0.0' })
  assert.match(synced, /\{ version: '99\.0\.0', date: '2026-10-24', tagged: false \},/)
  assert.doesNotMatch(synced, /status: 'merged-unreleased'/)
  assert.equal(syncRoadmap(synced, { ...SYNC, version: '99.0.0' }), synced)
})

test('syncRoadmapPageDoc updates the latest shipped line', () => {
  assert.equal(
    syncRoadmapPageDoc(' *\n * Latest shipped: v0.21.1 (2026-10-23)\n */', { version: '0.21.2', date: '2026-10-24' }),
    ' *\n * Latest shipped: v0.21.2 (2026-10-24)\n */',
  )
})
